<?php declare(strict_types=1); ?>
<section class="view hidden" id="view-registrations" data-title="My registrations" data-section="Student workspace"><div class="page-heading"><div><span class="eyebrow">YOUR ACTIVITY</span><h1>My registrations</h1><p class="muted">Keep track of the experiences you have signed up for.</p></div><button class="button button-primary" data-view="events">Find an event <span>→</span></button></div><div class="tabs"><button class="tab active" data-tab="current">Current <span><?= e(count($userRegistrations)) ?></span></button></div><div class="panel registration-table" id="tab-current"><div class="table-row table-head"><span>Event</span><span>Date &amp; time</span><span>Status</span><span></span></div><?php if ($userRegistrations === []): ?><div class="empty-state"><h3>No event registrations yet</h3><p class="muted">Find an event and reserve your place.</p></div><?php else: foreach ($userRegistrations as $registration): ?><div class="table-row"><span class="table-event"><span class="date-tile"><strong><?= e(date('d', strtotime((string) $registration['event_date']))) ?></strong><small><?= e(strtoupper(date('M', strtotime((string) $registration['event_date'])))) ?></small></span><strong><?= e($registration['title']) ?><small><?= e($registration['club_name']) ?></small></strong></span><span><?= e(date('j M Y', strtotime((string) $registration['event_date']))) ?><br><small><?= e(date('g:i A', strtotime((string) $registration['event_time']))) ?></small></span><span class="tag <?= $registration['status'] === 'attended' ? 'tag-green' : 'tag-blue' ?>"><?= e(ucfirst((string) $registration['status'])) ?></span><?php if ($registration['status'] === 'registered'): ?><form method="post" action="index.php?action=cancel-registration"><input type="hidden" name="_csrf" value="<?= e(\ClubConnect\Config\Csrf::token()) ?>"><input type="hidden" name="id" value="<?= (int) $registration['event_id'] ?>"><button class="text-button" type="submit">Cancel</button></form><?php else: ?><span></span><?php endif; ?></div><?php endforeach; endif; ?></div></section>
